```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int ostatnia = liczba % 10;
        int kopia = liczba;
        while (kopia >= 10) kopia /= 10;
        int pierwsza = kopia;
        int suma = pierwsza + ostatnia;
        int reszta = liczba % suma;
        cout << liczba << ": pierwsza=" << pierwsza
             << ", ostatnia=" << ostatnia
             << ", suma=" << suma
             << ", " << liczba << " % " << suma << " = " << reszta;
        if (reszta == 0) {
            cout << " -> TAK" << endl;
            ile++;
        } else {
            cout << " -> NIE" << endl;
        }
    }
    cout << "Liczb podzielnych przez sume pierwszej i ostatniej cyfry: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Wyodrebniamy pierwsza i ostatnia cyfre, sumujemy je, sprawdzamy podzielnosc. Liczby sa > 9, wiec pierwsza cyfra >= 1, a suma >= 1 — brak ryzyka dzielenia przez zero.

